110	    /**
111	     * Builds the read representation of a persisted owner, populating the derived fields
112	     * ({@code householdSize}, {@code bulkSignupWarning}) that are not stored on the entity.
113	     */
114	    private OwnerDto toOwnerDtoWithDerived(Owner owner) {
115	        owner.setHouseholdSize(this.clinicService.countOwnersByHouseholdId(owner.getHouseholdId()));
116	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
117	        ownerDto.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
118	        return ownerDto;
119	    }
120	
121	    /**
122	     * Whether more than 80 owners have already been created on {@code registrationDate},
123	     * signalling a bulk-signup surge for the read-only {@code bulkSignupWarning} field.
124	     */
125	    private boolean isBulkSignup(LocalDate registrationDate) {
126	        return this.clinicService.countOwnersByRegistrationDate(registrationDate) > 80;
127	    }
128	
129	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
130	    @Override
131	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
132	        // Idempotent replay: a repeat with an already-seen key returns the originally created
133	        // owner with 200 rather than creating (and possibly rejecting as) a duplicate.
134	        Integer existingId = this.clinicService.findOwnerIdByIdempotencyKey(idempotencyKey);
135	        if (existingId != null) {
136	            Owner existing = this.clinicService.findOwnerById(existingId);
137	            if (existing != null) {
138	                return new ResponseEntity<>(toOwnerDtoWithDerived(existing), HttpStatus.OK);
139	            }
140	        }
141	        HttpHeaders headers = new HttpHeaders();
142	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
143	        LocalDate registrationDate = owner.resolveRegistrationDate();
144	        if (this.clinicService.countOwnersByRegistrationDate(registrationDate) >= 100) {
145	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
146	        }
147	        if (this.clinicService.countOwnersByCity(owner.getCity()) >= 50) {
148	            return new ResponseEntity<>(HttpStatus.CONFLICT);
149	        }
150	        // The household id is deterministic: owners that share a (normalized lastName, postcode)
151	        // share it automatically. It feeds the membership-level cap and household sizing below.
152	        owner.setHouseholdId(this.clinicService.computeHouseholdId(owner));
153	        // A new owner joining an existing household (owners sharing a normalized lastName and
154	        // postcode) has its membershipLevel capped at one above the current maximum membershipLevel
155	        // among the existing household members. With no existing household member, no cap applies.
156	        owner.setMembershipLevelCap(this.clinicService.computeMembershipLevelCap(owner.getHouseholdId()));
157	        // Hard duplicate detection is consolidated into the owner's derived identity key (see
158	        // Owner#getIdentityKey): reject only when the new owner's whole key matches an existing one.
159	        // There is no separate household-duplicate 409: two owners sharing a lastName and postcode
160	        // but differing in telephone (or email) have distinct identity keys and are allowed.
161	        if (this.clinicService.existsOwnerWithIdentityKey(owner.getIdentityKey())) {
162	            return new ResponseEntity<>(HttpStatus.CONFLICT);
163	        }
164	        // Soft-match: the identity key differs, yet the surname's soundex and the postcode match an
165	        // existing owner, flagged 'possibleDuplicate'. This is exactly the same lastName/postcode,
166	        // different telephone case that is no longer a hard duplicate.
167	        Integer possibleDuplicateOf = this.clinicService.findPossibleDuplicateOwnerId(owner);
168	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
169	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
170	        owner.setNamesakeCount(
171	            this.clinicService.countOwnersByName(owner.getFirstName(), owner.getLastName()));
172	        this.clinicService.saveOwner(owner);
173	        this.clinicService.registerIdempotencyKey(idempotencyKey, owner.getId());
174	        OwnerDto ownerDto = toOwnerDtoWithDerived(owner);
175	        auditLogger.info(
176	            "owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
177	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
178	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
179	        // Immutable structured event, in addition to the human-readable line above. It carries the
180	        // owner's CURRENT primary identifier (Owner#primaryIdentifier) so that when the customerCode
181	        // is later unified into the memberId, the event follows without touching this call site.
182	        this.ownerAuditEvents.ownerCreated(
183	            owner.getId(), owner.primaryIdentifier(), ownerDto.getMembershipLevel());
184	        headers.setLocation(UriComponentsBuilder.newInstance()
185	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
186	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
187	    }
