189	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
190	    @Override
191	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
192	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
193	        if (currentOwner == null) {
194	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
195	        }
196	        currentOwner.setAddressLine1(ownerMapper.normalizeAddress(ownerFieldsDto.getAddressLine1()));
197	        currentOwner.setAddressLine2(ownerMapper.normalizeAddress(ownerFieldsDto.getAddressLine2()));
198	        currentOwner.setAddress(AddressNormalizer.compose(
199	            currentOwner.getAddressLine1(), currentOwner.getAddressLine2(),
200	            ownerMapper.normalizeAddress(ownerFieldsDto.getAddress())));
201	        currentOwner.setCity(ownerFieldsDto.getCity());
202	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
203	        currentOwner.setLastName(ownerFieldsDto.getLastName());
204	        currentOwner.setTelephone(ownerMapper.normalizeTelephone(ownerFieldsDto.getTelephone()));
205	        currentOwner.setEmail(ownerFieldsDto.getEmail());
206	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
207	        this.clinicService.saveOwner(currentOwner);
208	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
209	    }
